"""Offline generator-only exact bbox intersection fallback; no ROS/runtime use."""
class Index:
    def __init__(self):
        self.items = []
    def insert(self, identifier, bounds, obj=None):
        self.items.append((identifier, tuple(bounds), obj))
    def intersection(self, bounds, objects=False):
        a, b, c, d = bounds
        for identifier, (x0, y0, x1, y1), obj in self.items:
            if x0 <= c and a <= x1 and y0 <= d and b <= y1:
                yield obj if objects == 'raw' else identifier
Rtree = Index
